`timescale 1ns / 1ps
//=============================================================================
// SLIME MAZE : colour sprites, made from the PNG files in art/
//   (generated by gen_art.py - edit the PNG files, not this file)
//
//   Each pixel is a 4-bit colour number (0 = transparent).
//   A palette module turns the colour number into a 12-bit {R, G, B} colour.
//   One row of a 32 x 32 sprite = 32 pixels x 4 bits = 128 bits, written in hex,
//   left pixel first.  All modules are combinational ROMs (LUTs).
//=============================================================================

//-----------------------------------------------------------------------------
// Palette for the slime, crown, pellet and icons (5-bit colour number)
//-----------------------------------------------------------------------------
module art_palette (
    input  wire [4:0]  ci,
    output reg  [11:0] rgb
);
    always @* begin
        case (ci)
            5'd1 : rgb = 12'h8F8;
            5'd2 : rgb = 12'h012;
            5'd3 : rgb = 12'h474;
            5'd4 : rgb = 12'h6C6;
            5'd5 : rgb = 12'hEC0;
            5'd6 : rgb = 12'h220;
            5'd7 : rgb = 12'h550;
            5'd8 : rgb = 12'hCA0;
            5'd9 : rgb = 12'hFD0;
            5'd10: rgb = 12'hF62;
            5'd11: rgb = 12'h0AF;
            5'd12: rgb = 12'hB53;
            5'd13: rgb = 12'h2C4;
            5'd14: rgb = 12'h092;
            5'd15: rgb = 12'h000;
            5'd16: rgb = 12'hD00;
            5'd17: rgb = 12'hFFF;
            default: rgb = 12'h000;
        endcase
    end
endmodule

