//-----------------------------------------------------------------------------
// Life icon, 8 x 8 : id 0 = life left, id 1 = life lost
//-----------------------------------------------------------------------------
module art_life (
    input  wire [0:0] id,
    input  wire [2:0] row,
    input  wire [2:0] col,
    output wire [4:0] ci          // colour number, 0 = transparent
);
    reg [39:0] r;
    always @* begin
        case ({id, row})
            // life_alive
            {1'd0, 3'd1}:      r = 40'h001EF7BC00;
            {1'd0, 3'd2}:      r = 40'h03DF083DE0;
            {1'd0, 3'd3}:      r = 40'h03E10841E0;
