//-----------------------------------------------------------------------------
// Palette for the ghosts
//-----------------------------------------------------------------------------
module ghost_palette (
    input  wire [3:0]  ci,
    output reg  [11:0] rgb
);
    always @* begin
        case (ci)
            4'd1 : rgb = 12'hF58;
            4'd2 : rgb = 12'hFFF;
            4'd3 : rgb = 12'h4DF;
            4'd4 : rgb = 12'hC6F;
            4'd5 : rgb = 12'h44F;
            4'd6 : rgb = 12'h000;
            default: rgb = 12'h000;
        endcase
    end
endmodule

